// Dev launcher: open any scene with a saved engine state.
//   ?scene=DeliveryScene&fixture=delivery     (omit fixture to use the scene's default)
// Fixtures live in ./fixtures/<name>.json and are generated by `npm run fixtures`.
import { Ferry } from '../ferry.js';
import { sceneFor } from '../router.js';

const fixtures = import.meta.glob('./fixtures/*.json', { eager: true, import: 'default' });
const byName = Object.fromEntries(
  Object.entries(fixtures).map(([p, v]) => [p.replace('./fixtures/', '').replace('.json', ''), v]),
);

export const FIXTURE_NAMES = Object.keys(byName);

/** Default fixture for a scene when ?fixture= is omitted. */
const DEFAULT_FIXTURE = {
  BoardingScene: 'boarding',
  CrossingScene: 'window',
  DeliveryScene: 'delivery',
  ReturnScene: 'return',
  GameOverScene: 'ended',
  ChoiceOverlay: 'choice',
  TrimOverlay: 'trim',
};

export function getFixture(name) {
  const s = byName[name];
  if (!s) throw new Error(`Unknown fixture "${name}". Available: ${FIXTURE_NAMES.join(', ')}`);
  return structuredClone(s);
}

/** If the URL has ?scene=, open that scene and return true. */
export function openFromQuery(router) {
  const q = new URLSearchParams(globalThis.location.search);
  const scene = q.get('scene');
  if (!scene) return false;
  const name = q.get('fixture') ?? DEFAULT_FIXTURE[scene];
  const state = name ? getFixture(name) : Ferry.create(1);
  console.log(
    `[ferry] dev launcher: ${scene} with fixture "${name ?? 'create(1)'}" (phase ${state.phase}, window ${state.window.kind}, router maps it to ${sceneFor(state)})`,
  );
  router.devOpen(scene, state);
  return true;
}

/** Tiny dev menu (top right) that reloads the page with the chosen scene and fixture. Dev server only. */
export function mountDevMenu(game, sceneKeys) {
  if (!import.meta.env.DEV) return;
  const host = document.getElementById('dev-menu');
  if (!host) return;
  const q = new URLSearchParams(globalThis.location.search);
  const opts = (items, cur, blank) =>
    `${blank ? '<option value="">(default)</option>' : ''}` +
    items.map((i) => `<option${i === cur ? ' selected' : ''}>${i}</option>`).join('');
  host.innerHTML =
    `<select id="dm-scene">${opts(sceneKeys, q.get('scene'))}</select>` +
    `<select id="dm-fix">${opts(FIXTURE_NAMES, q.get('fixture'), true)}</select>` +
    '<button id="dm-go">Open</button>';
  host.querySelector('#dm-go').onclick = () => {
    const p = new URLSearchParams({ scene: host.querySelector('#dm-scene').value });
    const f = host.querySelector('#dm-fix').value;
    if (f) p.set('fixture', f);
    globalThis.location.search = '?' + p;
  };
}
